const PORT = process.env.PORT || 3000;

// Embedded Fallback Static Assets for Vercel Serverless Function Execution
const EMBEDDED_INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n    <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n    <meta name=\"theme-color\" content=\"#0d1117\">\n    <title>Khan Telecom ISP Portal</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"/assets/css/kt-app.css?v=2.2.0\">\n</head>\n<body class=\"kt-app-body\">\n    <!-- App Shell Layout -->\n    <div class=\"kt-app-shell\">\n\n        <!-- Header Status Bar -->\n        <header class=\"kt-header\">\n            <div class=\"header-left\">\n                <button id=\"kt-drawer-toggle\" class=\"btn-icon\" aria-label=\"Toggle Menu\">\n                    <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"3\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"3\" y1=\"18\" x2=\"21\" y2=\"18\"></line></svg>\n                </button>\n                <div class=\"kt-logo\">\n                    <img src=\"/assets/img/logo.png\" alt=\"Khan Telecom\" class=\"kt-logo-img\">\n                    <div class=\"logo-text\">\n                        <h2>KHAN TELECOM</h2>\n                        <span class=\"badge-status\">LIVE SYNC</span>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"header-right\">\n                <div class=\"user-pill\">\n                    <div class=\"user-avatar\">S</div>\n                    <div class=\"user-info hide-mobile\">\n                        <span class=\"user-name\">Saif Telecom</span>\n                        <span class=\"user-role\">SUPER ADMIN</span>\n                    </div>\n                </div>\n                <button id=\"btn-open-change-pass-modal\" onclick=\"KT_App.openChangePasswordModal()\" class=\"btn btn-sm btn-secondary\" title=\"Change Password\">🔑 Password</button>\n                <button id=\"kt-logout-btn\" class=\"btn btn-sm btn-outline-danger\" title=\"Logout\">Logout</button>\n            </div>\n        </header>\n\n        <div class=\"kt-main-wrapper\">\n            <!-- Collapsible Sidebar & Mobile Drawer -->\n            <aside id=\"kt-sidebar\" class=\"kt-sidebar\">\n                <nav class=\"sidebar-nav\">\n                    <a href=\"#dashboard\" class=\"nav-item active\" data-view=\"dashboard\" onclick=\"KT_App.switchView('dashboard')\">\n                        <span class=\"nav-icon\">📊</span>\n                        <span class=\"nav-text\">Dashboard</span>\n                    </a>\n                    <a href=\"#customers\" class=\"nav-item\" data-view=\"customers\" onclick=\"KT_App.switchView('customers')\">\n                        <span class=\"nav-icon\">👥</span>\n                        <span class=\"nav-text\">Customers</span>\n                    </a>\n                    <a href=\"#packages\" class=\"nav-item\" data-view=\"packages\" onclick=\"KT_App.switchView('packages')\">\n                        <span class=\"nav-icon\">⚡</span>\n                        <span class=\"nav-text\">Packages</span>\n                    </a>\n                    <a href=\"#products\" class=\"nav-item\" data-view=\"products\" onclick=\"KT_App.switchView('products')\">\n                        <span class=\"nav-icon\">📦</span>\n                        <span class=\"nav-text\">Products & Stock</span>\n                    </a>\n                    <a href=\"#invoices\" class=\"nav-item\" data-view=\"invoices\" onclick=\"KT_App.switchView('invoices')\">\n                        <span class=\"nav-icon\">📄</span>\n                        <span class=\"nav-text\">Invoices & Recovery</span>\n                    </a>\n                    <a href=\"#staff\" class=\"nav-item\" data-view=\"staff\" onclick=\"KT_App.switchView('staff')\">\n                        <span class=\"nav-icon\">🔐</span>\n                        <span class=\"nav-text\">Staff Matrix</span>\n                    </a>\n                    <a href=\"#logs\" class=\"nav-item\" data-view=\"logs\" onclick=\"KT_App.switchView('logs')\">\n                        <span class=\"nav-icon\">📜</span>\n                        <span class=\"nav-text\">Activity Logs</span>\n                    </a>\n                    <a href=\"#settings\" class=\"nav-item\" data-view=\"settings\" onclick=\"KT_App.switchView('settings')\">\n                        <span class=\"nav-icon\">⚙️</span>\n                        <span class=\"nav-text\">Settings & Import</span>\n                    </a>\n                </nav>\n                \n                <div class=\"sidebar-footer\">\n                    <p>Khan Telecom v1.0.0</p>\n                </div>\n            </aside>\n\n            <!-- Central Viewport -->\n            <main id=\"kt-viewport\" class=\"kt-viewport\">\n                <div id=\"kt-view-loader\" class=\"kt-loader\" style=\"display:none;\">\n                    <div class=\"spinner\"></div>\n                </div>\n\n                <div id=\"kt-view-content\" class=\"view-container\">\n                    <!-- Views render dynamically via kt-app.js -->\n                </div>\n            </main>\n        </div>\n\n        <!-- Footer Bar -->\n        <footer class=\"kt-app-footer\">\n            <span>Khan Telecom ISP Engine &copy; 2026</span>\n        </footer>\n    </div>\n\n    <!-- Modals Container -->\n    <div id=\"kt-modal-backdrop\" class=\"kt-modal-backdrop\" style=\"display: none;\"></div>\n\n    <!-- 1. Customer Modal -->\n    <div id=\"kt-customer-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h3 id=\"customer-modal-title\">Register New Customer</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <form id=\"kt-customer-form\">\n                <input type=\"hidden\" name=\"id\" value=\"0\">\n                <div class=\"modal-body grid-2\">\n                    <div class=\"form-group\">\n                        <label>Subscriber Code / Account ID *</label>\n                        <input type=\"text\" name=\"customer_code\" required placeholder=\"e.g. KT-1001 or 1001\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Full Name *</label>\n                        <input type=\"text\" name=\"full_name\" required placeholder=\"e.g. Muhammad Ali\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Phone Number (WhatsApp) *</label>\n                        <input type=\"text\" name=\"phone_number\" required placeholder=\"03001234567\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>CNIC ID</label>\n                        <input type=\"text\" name=\"cnic_id\" placeholder=\"35202-0000000-0\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Area / Sector *</label>\n                        <input type=\"text\" name=\"area_sector\" required placeholder=\"Sector F-11 / Phase 2\">\n                    </div>\n                    <div class=\"form-group span-2\">\n                        <label>Full Address</label>\n                        <textarea name=\"address\" rows=\"2\" placeholder=\"House #, Street #...\"></textarea>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>ISP Package *</label>\n                        <select name=\"package_id\" id=\"cust-package-select\" required></select>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Assigned IP / IPOE</label>\n                        <input type=\"text\" name=\"assigned_ip_ipoe\" placeholder=\"192.168.10.50\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Connection Type</label>\n                        <select name=\"connection_type\">\n                            <option value=\"Fiber_FTTH\">Fiber FTTH</option>\n                            <option value=\"Wireless\">Wireless</option>\n                            <option value=\"Ethernet\">Ethernet</option>\n                        </select>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Billing Cycle Day (1-31)</label>\n                        <input type=\"number\" name=\"billing_cycle_day\" min=\"1\" max=\"31\" value=\"1\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Status & 30-Day Package Cycle</label>\n                        <select name=\"status\">\n                            <option value=\"active\">🟢 Active (Start / Renew 30-Day Package)</option>\n                            <option value=\"inactive\">🔴 Inactive / Expired</option>\n                            <option value=\"suspended\">⚠️ Suspended</option>\n                            <option value=\"pending\">⏳ Pending Installation</option>\n                        </select>\n                    </div>\n                </div>\n                <div class=\"modal-footer flex-between\">\n                    <button type=\"button\" id=\"btn-delete-customer-modal\" class=\"btn btn-outline-danger\" style=\"font-size:13px; display:none;\">🗑️ Delete Subscriber</button>\n                    <div>\n                        <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                        <button type=\"submit\" class=\"btn btn-primary\">Save</button>\n                    </div>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 2. Package Modal -->\n    <div id=\"kt-package-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h3 id=\"package-modal-title\">Create Package Tier</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <form id=\"kt-package-form\">\n                <input type=\"hidden\" name=\"id\" value=\"0\">\n                <div class=\"modal-body grid-2\">\n                    <div class=\"form-group span-2\">\n                        <label>Package Name *</label>\n                        <input type=\"text\" name=\"package_name\" required placeholder=\"e.g. 20 Mbps Fiber Pro\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Speed (Mbps) *</label>\n                        <input type=\"number\" name=\"speed_mbps\" required min=\"1\" value=\"20\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Status</label>\n                        <select name=\"status\">\n                            <option value=\"active\">Active</option>\n                            <option value=\"inactive\">Inactive</option>\n                        </select>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Upstream Cost Price (PKR) *</label>\n                        <input type=\"number\" step=\"0.01\" id=\"pkg-cost\" name=\"cost_price\" required value=\"1000\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Retail Sale Price (PKR) *</label>\n                        <input type=\"number\" step=\"0.01\" id=\"pkg-sale\" name=\"sale_price\" required value=\"2000\">\n                    </div>\n                    <div class=\"form-group span-2 margin-calc-box\">\n                        <span>Calculated Profit Margin / Subscriber:</span>\n                        <strong id=\"pkg-margin-preview\">PKR 1000.00</strong>\n                    </div>\n                </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                    <button type=\"submit\" class=\"btn btn-primary\">Save</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 3. Create Invoice Modal -->\n    <div id=\"kt-invoice-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h3>Generate Customer Invoice</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <form id=\"kt-invoice-form\">\n                <div class=\"modal-body\">\n                    <div class=\"form-group\">\n                        <label>Select Customer *</label>\n                        <select name=\"customer_id\" id=\"invoice-customer-select\" required></select>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Billing Month *</label>\n                        <input type=\"month\" name=\"billing_month\" required value=\"2026-09\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Initial Payment Status</label>\n                        <select name=\"payment_status\">\n                            <option value=\"unpaid\">Unpaid</option>\n                            <option value=\"paid\">Paid (Collected)</option>\n                        </select>\n                    </div>\n                </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                    <button type=\"submit\" class=\"btn btn-primary\">Save</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 4. Collect Fee Payment Modal -->\n    <div id=\"kt-payment-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h3>Collect Customer Payment</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <form id=\"kt-payment-form\">\n                <input type=\"hidden\" name=\"invoice_id\" id=\"pay-invoice-id\" value=\"0\">\n                <div class=\"modal-body grid-2\">\n                    <div class=\"form-group span-2 info-box\">\n                        <span id=\"pay-customer-name\">Customer</span>\n                        <strong id=\"pay-due-amount\">Due: PKR 0.00</strong>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Amount Paid (PKR) *</label>\n                        <input type=\"number\" step=\"0.01\" name=\"amount_paid\" id=\"pay-amount-input\" required>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Discount (PKR)</label>\n                        <input type=\"number\" step=\"0.01\" name=\"discount\" value=\"0\">\n                    </div>\n                    <div class=\"form-group span-2\">\n                        <label>Payment Method</label>\n                        <select name=\"payment_method\">\n                            <option value=\"cash\">Cash Settlement</option>\n                            <option value=\"bank_transfer\">Bank Transfer</option>\n                            <option value=\"easypaisa_jazzcash\">Easypaisa / JazzCash</option>\n                        </select>\n                    </div>\n                </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                    <button type=\"submit\" class=\"btn btn-success\">Save</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 5. Thermal Receipt & WhatsApp Modal -->\n    <div id=\"kt-receipt-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content modal-receipt\">\n            <div class=\"modal-header\">\n                <h3>Payment Confirmation & Slip</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <div class=\"modal-body\">\n                <div id=\"receipt-preview-container\"></div>\n            </div>\n            <div class=\"modal-footer\" style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 16px 20px;\">\n                <button type=\"button\" id=\"btn-save-image-slip\" class=\"btn btn-primary\" style=\"font-size:14px; padding:12px; font-weight:700; width:100%;\">💾 Save Image</button>\n                <a id=\"btn-whatsapp-send\" href=\"#\" target=\"_blank\" class=\"btn btn-whatsapp\" style=\"font-size:14px; padding:12px; font-weight:700; width:100%; text-decoration:none; justify-content:center;\">\n                    <span>📱 Send WhatsApp Slip</span>\n                </a>\n            </div>\n        </div>\n    </div>\n    <!-- 6. Subscriber Dues & Payment History Ledger Modal -->\n    <div id=\"kt-ledger-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h3 id=\"ledger-modal-title\">Subscriber Payment History Ledger</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <div class=\"modal-body\">\n                <div id=\"ledger-summary-box\" class=\"info-box margin-calc-box\" style=\"margin-bottom:16px;\">\n                    <div>\n                        <span id=\"ledger-cust-name\" style=\"font-weight:bold; display:block;\">Subscriber Name</span>\n                        <span id=\"ledger-cust-code\" style=\"font-size:12px; color:var(--text-muted);\">KT-1001</span>\n                    </div>\n                    <div style=\"text-align:right;\">\n                        <span style=\"font-size:11px; display:block;\">Current Dues Balance</span>\n                        <strong id=\"ledger-cust-balance\" style=\"color:#ff7b72; font-size:16px;\">PKR 0.00</strong>\n                    </div>\n                </div>\n\n                <div class=\"kt-table-container\">\n                    <table class=\"kt-table\">\n                        <thead>\n                            <tr>\n                                <th>Month / Inv No</th>\n                                <th>Amount Due</th>\n                                <th>Paid</th>\n                                <th>Discount</th>\n                                <th>Status</th>\n                                <th>Collector & Date</th>\n                            </tr>\n                        </thead>\n                        <tbody id=\"ledger-table-body\">\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n            <div class=\"modal-footer\">\n                <button type=\"button\" class=\"btn btn-secondary modal-close\">Close Ledger</button>\n            </div>\n        </div>\n    </div>\n\n    <!-- 7. Buy / Add Product Stock Modal -->\n    <div id=\"kt-product-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h3 id=\"product-modal-title\">Buy / Add Hardware Product Stock</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <form id=\"kt-product-form\">\n                <input type=\"hidden\" name=\"id\" value=\"0\">\n                <div class=\"modal-body grid-2\">\n                    <div class=\"form-group span-2\">\n                        <label>Product Name *</label>\n                        <input type=\"text\" name=\"product_name\" required placeholder=\"e.g. Dual Band AC1200 WiFi Router\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Category</label>\n                        <select name=\"category\">\n                            <option value=\"Routers\">Routers</option>\n                            <option value=\"Cables\">Fiber/LAN Cables</option>\n                            <option value=\"ONU/ONT\">ONU/ONT Devices</option>\n                            <option value=\"Accessories\">Accessories & Patch Cords</option>\n                        </select>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Unit Type</label>\n                        <input type=\"text\" name=\"unit\" value=\"pcs\" placeholder=\"pcs / meters / box\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Wholesale Buying Cost Price (PKR) *</label>\n                        <input type=\"number\" step=\"0.01\" id=\"prod-cost\" name=\"cost_price\" required value=\"4000\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Retail Selling Price (PKR) *</label>\n                        <input type=\"number\" step=\"0.01\" id=\"prod-sale\" name=\"sale_price\" required value=\"6000\">\n                    </div>\n                    <div class=\"form-group span-2\">\n                        <label>Buying Stock Quantity Purchased *</label>\n                        <input type=\"number\" name=\"stock_qty\" required min=\"1\" value=\"10\">\n                    </div>\n                </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                    <button type=\"submit\" class=\"btn btn-success\">Save</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 8. Sell Product to Subscriber Modal -->\n    <div id=\"kt-sell-product-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h3>Sell Hardware Equipment to Subscriber</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <form id=\"kt-sell-product-form\">\n                <div class=\"modal-body grid-2\">\n                    <div class=\"form-group span-2\">\n                        <label>Select Hardware Product *</label>\n                        <select name=\"product_id\" id=\"sell-product-select\" required></select>\n                    </div>\n                    <div class=\"form-group span-2\">\n                        <label>Select Subscriber *</label>\n                        <select name=\"customer_id\" id=\"sell-customer-select\" required></select>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Quantity Sold *</label>\n                        <input type=\"number\" name=\"quantity\" id=\"sell-qty-input\" required min=\"1\" value=\"1\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Unit Retail Price (PKR)</label>\n                        <input type=\"text\" id=\"sell-unit-price\" readonly value=\"PKR 0.00\">\n                    </div>\n                    <div class=\"form-group span-2 margin-calc-box\">\n                        <span>Auto-Calculated Total Bill:</span>\n                        <strong id=\"sell-total-preview\" style=\"color:#7ee787; font-size:18px;\">PKR 0.00</strong>\n                    </div>\n                </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                    <button type=\"submit\" class=\"btn btn-success\">Save</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 9. User Login Modal -->\n    <div id=\"kt-login-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\" style=\"max-width: 450px;\">\n            <div class=\"modal-header\">\n                <h3>Portal Staff Sign In</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <div id=\"kt-login-alert\" class=\"kt-alert\" style=\"display: none; margin: 15px 24px 0 24px;\"></div>\n            <form id=\"kt-login-form\">\n                <div class=\"modal-body\">\n                    <div class=\"form-group\">\n                        <label>Username / Staff ID *</label>\n                        <input type=\"text\" id=\"login-username\" name=\"log\" required placeholder=\"Enter username\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Password *</label>\n                        <input type=\"password\" id=\"login-password\" name=\"pwd\" required placeholder=\"••••••••\">\n                    </div>\n                </div>\n                <div class=\"modal-footer flex-between\">\n                    <button type=\"button\" id=\"btn-open-register-modal\" class=\"btn btn-sm btn-secondary\">➕ Request Staff Registration</button>\n                    <button type=\"submit\" id=\"kt-login-btn\" class=\"btn btn-primary\">Sign In</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 10. Staff Registration Request Modal -->\n    <div id=\"kt-staff-register-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\" style=\"max-width: 500px;\">\n            <div class=\"modal-header\">\n                <h3>Request Staff Account Registration</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <form id=\"kt-register-form\">\n                <div class=\"modal-body grid-2\">\n                    <div class=\"form-group span-2\">\n                        <label>Full Name *</label>\n                        <input type=\"text\" name=\"fullname\" required placeholder=\"e.g. Tariq Mehmood\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Desired Username *</label>\n                        <input type=\"text\" name=\"username\" required placeholder=\"e.g. tariq_field\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Password *</label>\n                        <input type=\"password\" name=\"password\" required value=\"staff123\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Email Address</label>\n                        <input type=\"email\" name=\"email\" placeholder=\"staff@khantelecom.com\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Requested Role Level</label>\n                        <select name=\"role_level\">\n                            <option value=\"employee\">Field Employee / Agent</option>\n                            <option value=\"admin\">Operations Admin</option>\n                        </select>\n                    </div>\n                    <div class=\"form-group span-2 info-box\" style=\"font-size: 12px;\">\n                        <span>⚠️ Note: New accounts require explicit Super Admin approval before you can log in.</span>\n                    </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                    <button type=\"submit\" class=\"btn btn-success\">Save</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 11. Change Super Admin Password Modal -->\n    <div id=\"kt-change-password-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <h3>Change Super Admin Password & Credentials</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <form id=\"kt-change-password-form\">\n                <div class=\"modal-body\">\n                    <div class=\"form-group\">\n                        <label>Super Admin Username</label>\n                        <input type=\"text\" name=\"new_username\" id=\"change-pass-username\" required placeholder=\"e.g. saif\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label>New Password *</label>\n                        <div style=\"position: relative;\">\n                            <input type=\"password\" name=\"new_password\" id=\"change-pass-new\" required placeholder=\"••••••••\" style=\"padding-right: 40px; width: 100%;\">\n                            <button type=\"button\" class=\"btn-toggle-pass\" data-target=\"#change-pass-new\" style=\"position: absolute; right: 10px; top: 50%; transform: translateY(-50%); background: transparent; border: none; cursor: pointer; font-size: 16px;\">👁️</button>\n                        </div>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>Confirm New Password *</label>\n                        <div style=\"position: relative;\">\n                            <input type=\"password\" name=\"confirm_password\" id=\"change-pass-confirm\" required placeholder=\"••••••••\" style=\"padding-right: 40px; width: 100%;\">\n                            <button type=\"button\" class=\"btn-toggle-pass\" data-target=\"#change-pass-confirm\" style=\"position: absolute; right: 10px; top: 50%; transform: translateY(-50%); background: transparent; border: none; cursor: pointer; font-size: 16px;\">👁️</button>\n                        </div>\n                    </div>\n                    <div class=\"form-group info-box\" style=\"font-size: 12px; margin-top: 10px;\">\n                        <span>🔒 Note: Changing Super Admin credentials updates login access across the entire portal in real time.</span>\n                    </div>\n                </div>\n                <div class=\"modal-footer\">\n                    <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                    <button type=\"submit\" class=\"btn btn-primary\">Save</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- 12. Double Entry / Duplicates Detection & Merge Modal -->\n    <div id=\"kt-duplicates-modal\" class=\"kt-modal\" style=\"display: none;\">\n        <div class=\"modal-content\" style=\"max-width: 850px; width: 95%;\">\n            <div class=\"modal-header\">\n                <h3>🔁 Double Entry Detection & Clean Merge Tool</h3>\n                <button class=\"btn-close modal-close\">&times;</button>\n            </div>\n            <div class=\"modal-body\">\n                <div id=\"duplicates-summary-box\" class=\"info-box margin-calc-box\" style=\"margin-bottom:16px; background: rgba(234, 179, 8, 0.1); border-color: rgba(234, 179, 8, 0.3);\">\n                    <div>\n                        <strong style=\"color:#eab308; font-size:15px; display:block;\">🔍 Duplicate Subscriber Scan Complete</strong>\n                        <span id=\"duplicates-scan-status\" style=\"font-size:12px; color:var(--text-muted);\">Detecting duplicate accounts...</span>\n                    </div>\n                </div>\n\n                <div class=\"kt-table-container\" style=\"max-height: 400px; overflow-y: auto;\">\n                    <table class=\"kt-table\">\n                        <thead>\n                            <tr>\n                                <th style=\"width:40px;\"><input type=\"checkbox\" id=\"chk-select-all-duplicates\" checked title=\"Select All\"></th>\n                                <th>Match Criteria</th>\n                                <th>Primary Account (To Keep)</th>\n                                <th>Duplicate Account(s) (To Merge & Remove)</th>\n                            </tr>\n                        </thead>\n                        <tbody id=\"duplicates-table-body\">\n                            <!-- Populated dynamically via KT_App.detectDuplicateSubscribers() -->\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n            <div class=\"modal-footer flex-between\">\n                <button type=\"button\" class=\"btn btn-secondary modal-close\">Cancel</button>\n                <button type=\"button\" id=\"btn-execute-merge-duplicates\" class=\"btn btn-warning\" style=\"font-weight:700;\">⚡ Replace & Merge Duplicates</button>\n            </div>\n        </div>\n    </div>\n\n    <script src=\"https://code.jquery.com/jquery-3.6.0.min.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js\"></script>\n    <script>\n        var ktConfig = {\n            ajaxUrl: '/api/ajax',\n            nonce: 'demo_nonce'\n        };\n    </script>\n    <script src=\"/assets/js/kt-app.js?v=2.5.0\"></script>\n</body>\n</html>\n";
const EMBEDDED_CSS_CONTENT = "/* Khan Telecom ISP Manager - Modern Glassmorphic Styling System */\n\n:root {\n    --bg-dark: #0b0f17;\n    --bg-card: rgba(22, 27, 34, 0.75);\n    --bg-card-hover: rgba(33, 38, 45, 0.85);\n    --border-color: rgba(255, 255, 255, 0.1);\n    --text-main: #f0f6fc;\n    --text-muted: #8b949e;\n    \n    --primary: #1f6feb;\n    --primary-hover: #388bfd;\n    --success: #238636;\n    --success-hover: #2ea043;\n    --warning: #d29922;\n    --danger: #da3633;\n    --accent: #a371f7;\n    --whatsapp: #25d366;\n\n    --font-family: 'Outfit', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n    --radius-sm: 6px;\n    --radius-md: 10px;\n    --radius-lg: 16px;\n    --shadow: 0 10px 30px rgba(0, 0, 0, 0.5);\n    --backdrop-blur: blur(14px);\n}\n\n* {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n}\n\nbody.kt-login-body,\nbody.kt-app-body {\n    background-color: var(--bg-dark);\n    background-image: radial-gradient(circle at 10% 20%, rgba(31, 111, 235, 0.15) 0%, transparent 40%),\n                      radial-gradient(circle at 90% 80%, rgba(163, 113, 247, 0.15) 0%, transparent 40%);\n    color: var(--text-main);\n    font-family: var(--font-family);\n    min-height: 100vh;\n    -webkit-font-smoothing: antialiased;\n}\n\n/* ==================== LOGIN VIEW ==================== */\n.kt-login-wrapper {\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    min-height: 100vh;\n    padding: 20px;\n}\n\n.kt-glass-card {\n    background: var(--bg-card);\n    backdrop-filter: var(--backdrop-blur);\n    -webkit-backdrop-filter: var(--backdrop-blur);\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-lg);\n    padding: 40px;\n    width: 100%;\n    max-width: 440px;\n    box-shadow: var(--shadow);\n}\n\n.kt-brand {\n    text-align: center;\n    margin-bottom: 30px;\n}\n\n.brand-icon {\n    font-size: 40px;\n    margin-bottom: 10px;\n}\n\n.kt-brand h1 {\n    font-size: 26px;\n    font-weight: 700;\n    letter-spacing: 1px;\n    color: #ffffff;\n}\n\n.brand-tagline {\n    font-size: 13px;\n    color: var(--text-muted);\n    text-transform: uppercase;\n    letter-spacing: 2px;\n}\n\n/* Forms */\n.form-group {\n    margin-bottom: 18px;\n    display: flex;\n    flex-direction: column;\n}\n\n.form-group label {\n    font-size: 13px;\n    font-weight: 500;\n    margin-bottom: 6px;\n    color: var(--text-muted);\n}\n\n.form-group input,\n.form-group select,\n.form-group textarea {\n    background: rgba(13, 17, 23, 0.8);\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-sm);\n    padding: 12px 14px;\n    color: var(--text-main);\n    font-family: var(--font-family);\n    font-size: 14px;\n    transition: all 0.2s ease;\n}\n\n.form-group input:focus,\n.form-group select:focus,\n.form-group textarea:focus {\n    outline: none;\n    border-color: var(--primary);\n    box-shadow: 0 0 0 3px rgba(31, 111, 235, 0.25);\n}\n\n/* Buttons */\n.btn {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    padding: 10px 18px;\n    border-radius: var(--radius-sm);\n    font-weight: 600;\n    font-size: 14px;\n    cursor: pointer;\n    border: none;\n    transition: all 0.2s ease;\n    text-decoration: none;\n    gap: 8px;\n}\n\n.btn-primary { background: var(--primary); color: #ffffff; }\n.btn-primary:hover { background: var(--primary-hover); transform: translateY(-1px); }\n\n.btn-success { background: var(--success); color: #ffffff; }\n.btn-success:hover { background: var(--success-hover); }\n\n.btn-secondary { background: rgba(255, 255, 255, 0.1); color: var(--text-main); }\n.btn-secondary:hover { background: rgba(255, 255, 255, 0.2); }\n\n.btn-outline-danger { background: transparent; border: 1px solid var(--danger); color: var(--danger); }\n.btn-outline-danger:hover { background: var(--danger); color: #ffffff; }\n\n.btn-whatsapp { background: var(--whatsapp); color: #ffffff; font-weight: 700; }\n.btn-whatsapp:hover { background: #1eb954; color: #ffffff; }\n\n.btn-block { width: 100%; }\n.btn-sm { padding: 6px 12px; font-size: 12px; }\n.btn-icon { background: none; border: none; color: var(--text-main); cursor: pointer; padding: 6px; }\n\n.action-btn-group {\n    display: flex !important;\n    flex-direction: row !important;\n    align-items: center !important;\n    justify-content: flex-end;\n    gap: 6px;\n    flex-wrap: nowrap !important;\n    white-space: nowrap !important;\n    width: 100%;\n}\n\n.action-btn-group .btn-sm {\n    white-space: nowrap !important;\n    flex-shrink: 0 !important;\n}\n\n/* Alerts */\n.kt-alert {\n    padding: 12px 16px;\n    border-radius: var(--radius-sm);\n    font-size: 13px;\n    margin-bottom: 20px;\n}\n.kt-alert-danger { background: rgba(218, 54, 51, 0.2); border: 1px solid var(--danger); color: #ff7b72; }\n.kt-alert-success { background: rgba(35, 134, 54, 0.2); border: 1px solid var(--success); color: #7ee787; }\n\n/* ==================== APP SHELL LAYOUT ==================== */\n.kt-app-shell {\n    display: flex;\n    flex-direction: column;\n    height: 100vh;\n    overflow: hidden;\n}\n\n.kt-header {\n    height: 64px;\n    background: var(--bg-card);\n    backdrop-filter: var(--backdrop-blur);\n    border-bottom: 1px solid var(--border-color);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 0 20px;\n    z-index: 100;\n}\n\n.header-left {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n}\n\n.kt-logo {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n}\n\n.kt-logo-img {\n    height: 46px;\n    width: 46px;\n    object-fit: cover;\n    border-radius: 50%;\n    background: #ffffff;\n    padding: 1px;\n    border: 2px solid rgba(218, 54, 51, 0.8);\n    box-shadow: 0 0 12px rgba(218, 54, 51, 0.4), 0 0 6px rgba(255, 255, 255, 0.2);\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\n    flex-shrink: 0;\n}\n\n.kt-logo-img:hover {\n    transform: scale(1.08) rotate(3deg);\n    box-shadow: 0 0 20px rgba(218, 54, 51, 0.7);\n}\n\n.logo-badge {\n    font-size: 24px;\n}\n\n.logo-text h2 {\n    font-size: 16px;\n    font-weight: 700;\n    line-height: 1.2;\n}\n\n.badge-status {\n    background: rgba(35, 134, 54, 0.25);\n    color: #7ee787;\n    font-size: 9px;\n    font-weight: 700;\n    padding: 2px 6px;\n    border-radius: 4px;\n    letter-spacing: 1px;\n}\n\n.header-right {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n}\n\n.user-pill {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    background: rgba(255, 255, 255, 0.05);\n    padding: 4px 12px 4px 6px;\n    border-radius: 30px;\n    border: 1px solid var(--border-color);\n}\n\n.user-avatar {\n    width: 32px;\n    height: 32px;\n    background: var(--primary);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-weight: 700;\n    font-size: 14px;\n}\n\n.user-name { font-size: 13px; font-weight: 600; display: block; }\n.user-role { font-size: 10px; color: var(--text-muted); display: block; }\n\n/* Wrapper & Sidebar */\n.kt-main-wrapper {\n    display: flex;\n    flex: 1;\n    overflow: hidden;\n}\n\n.kt-sidebar {\n    width: 240px;\n    background: var(--bg-card);\n    backdrop-filter: var(--backdrop-blur);\n    border-right: 1px solid var(--border-color);\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n    transition: transform 0.3s ease;\n    z-index: 90;\n}\n\n.sidebar-nav {\n    padding: 20px 10px;\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n}\n\n.nav-item {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 12px 16px;\n    color: var(--text-muted);\n    text-decoration: none;\n    border-radius: var(--radius-sm);\n    font-size: 14px;\n    font-weight: 500;\n    transition: all 0.2s ease;\n}\n\n.nav-item:hover,\n.nav-item.active {\n    background: rgba(31, 111, 235, 0.15);\n    color: var(--text-main);\n    border-left: 3px solid var(--primary);\n}\n\n.sidebar-footer {\n    padding: 20px;\n    border-top: 1px solid var(--border-color);\n    font-size: 11px;\n    color: var(--text-muted);\n    text-align: center;\n}\n\n/* Viewport */\n.kt-viewport {\n    flex: 1;\n    overflow-y: auto;\n    padding: 24px;\n    background: transparent;\n}\n\n.view-container {\n    max-width: 1300px;\n    margin: 0 auto;\n}\n\n/* Footer Bar */\n.kt-app-footer {\n    height: 36px;\n    background: rgba(11, 15, 23, 0.95);\n    border-top: 1px solid var(--border-color);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 0 20px;\n    font-size: 11px;\n    color: var(--text-muted);\n}\n\n/* ==================== METRICS & CARDS ==================== */\n.metrics-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 20px;\n    margin-bottom: 24px;\n}\n\n.metric-card {\n    background: var(--bg-card);\n    backdrop-filter: var(--backdrop-blur);\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-md);\n    padding: 20px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    box-shadow: var(--shadow);\n}\n\n.metric-card-clickable {\n    cursor: pointer !important;\n    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1) !important;\n    position: relative;\n    user-select: none;\n}\n\n.metric-card-clickable:hover {\n    transform: translateY(-4px) scale(1.02) !important;\n    border-color: var(--primary) !important;\n    box-shadow: 0 12px 30px rgba(31, 111, 235, 0.3) !important;\n    background: rgba(33, 38, 45, 0.95) !important;\n}\n\n.metric-card-clickable:active {\n    transform: translateY(-1px) scale(0.99) !important;\n}\n\n.metric-info h3 {\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    color: var(--text-muted);\n    margin-bottom: 6px;\n}\n\n.metric-value {\n    font-size: 24px;\n    font-weight: 700;\n    color: #ffffff;\n}\n\n.metric-icon {\n    font-size: 32px;\n    opacity: 0.8;\n}\n\n/* Section Header & Data Tables */\n.section-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 20px;\n    flex-wrap: wrap;\n    gap: 16px;\n}\n\n.section-title {\n    font-size: 20px;\n    font-weight: 700;\n}\n\n.filter-bar {\n    display: flex;\n    gap: 12px;\n    flex-wrap: wrap;\n}\n\n.kt-table-container {\n    background: var(--bg-card);\n    backdrop-filter: var(--backdrop-blur);\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-md);\n    overflow-x: auto;\n    box-shadow: var(--shadow);\n}\n\n.kt-table {\n    width: 100%;\n    border-collapse: collapse;\n    text-align: left;\n    font-size: 13px;\n}\n\n.kt-table th {\n    background: rgba(255, 255, 255, 0.04);\n    color: var(--text-muted);\n    font-weight: 600;\n    padding: 14px 16px;\n    border-bottom: 1px solid var(--border-color);\n    text-transform: uppercase;\n    font-size: 11px;\n    letter-spacing: 0.5px;\n}\n\n.kt-table td {\n    padding: 14px 16px;\n    border-bottom: 1px solid var(--border-color);\n    color: var(--text-main);\n    white-space: nowrap;\n}\n\n.kt-table tbody tr:hover {\n    background: rgba(255, 255, 255, 0.03);\n}\n\n/* Badges */\n.badge {\n    padding: 4px 10px;\n    border-radius: 20px;\n    font-size: 11px;\n    font-weight: 600;\n    text-transform: uppercase;\n    display: inline-block;\n}\n\n.badge-active, .badge-paid { background: rgba(35, 134, 54, 0.2); color: #7ee787; border: 1px solid rgba(35, 134, 54, 0.4); }\n.badge-suspended, .badge-unpaid { background: rgba(218, 54, 51, 0.2); color: #ff7b72; border: 1px solid rgba(218, 54, 51, 0.4); }\n.badge-pending, .badge-partial { background: rgba(210, 153, 34, 0.2); color: #d29922; border: 1px solid rgba(210, 153, 34, 0.4); }\n\n/* ==================== MODALS ==================== */\n.kt-modal-backdrop {\n    position: fixed;\n    top: 0; left: 0; right: 0; bottom: 0;\n    background: rgba(0, 0, 0, 0.8);\n    backdrop-filter: blur(8px);\n    z-index: 9998;\n}\n\n.kt-modal {\n    position: fixed;\n    top: 50%; left: 50%;\n    transform: translate(-50%, -50%);\n    width: 92%;\n    max-width: 580px;\n    max-height: 90vh;\n    background: #161b22;\n    border: 1px solid rgba(255, 255, 255, 0.15);\n    border-radius: 12px;\n    box-shadow: 0 25px 60px rgba(0, 0, 0, 0.9), 0 0 1px rgba(255, 255, 255, 0.2);\n    z-index: 9999;\n    flex-direction: column;\n    overflow: hidden;\n}\n\n.modal-content {\n    display: flex;\n    flex-direction: column;\n    width: 100%;\n    height: 100%;\n    max-height: 85vh;\n}\n\n.modal-content form {\n    display: flex;\n    flex-direction: column;\n    flex: 1;\n    min-height: 0;\n    overflow: hidden;\n}\n\n.modal-header {\n    padding: 18px 24px;\n    border-bottom: 1px solid var(--border-color);\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    flex-shrink: 0;\n}\n\n.modal-header h3 { font-size: 18px; font-weight: 700; }\n.btn-close { font-size: 24px; color: var(--text-muted); background: none; border: none; cursor: pointer; }\n\n.modal-body {\n    padding: 24px;\n    overflow-y: auto;\n    flex: 1;\n}\n\n.modal-footer {\n    padding: 16px 24px;\n    border-top: 1px solid var(--border-color);\n    display: flex;\n    justify-content: flex-end;\n    gap: 12px;\n    background: #0f141c;\n    flex-shrink: 0;\n}\n\n.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }\n.span-2 { grid-column: span 2; }\n.flex-between { display: flex; justify-content: space-between; align-items: center; }\n\n.margin-calc-box {\n    background: rgba(31, 111, 235, 0.1);\n    border: 1px dashed var(--primary);\n    padding: 12px;\n    border-radius: var(--radius-sm);\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.info-box {\n    background: rgba(255, 255, 255, 0.05);\n    border-left: 4px solid var(--accent);\n    padding: 14px;\n    border-radius: var(--radius-sm);\n}\n\n/* Spinner Loader */\n.kt-loader {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    padding: 60px;\n    color: var(--text-muted);\n}\n\n.spinner {\n    width: 36px;\n    height: 36px;\n    border: 3px solid rgba(255, 255, 255, 0.1);\n    border-top-color: var(--primary);\n    border-radius: 50%;\n    animation: spin 0.8s linear infinite;\n    margin-bottom: 12px;\n}\n\n@keyframes spin { to { transform: rotate(360deg); } }\n\n/* ==================== THERMAL RECEIPT SLIP STYLING ==================== */\n.kt-thermal-slip {\n    background: #ffffff;\n    color: #000000;\n    font-family: 'Courier New', Courier, monospace;\n    width: 280px;\n    margin: 0 auto;\n    padding: 15px;\n    box-shadow: 0 4px 15px rgba(0,0,0,0.2);\n    border-radius: 4px;\n    font-size: 12px;\n    line-height: 1.3;\n}\n\n.slip-header { text-align: center; }\n.slip-header h2 { font-size: 16px; font-weight: bold; margin-bottom: 2px; }\n.slip-subtitle { font-size: 10px; margin-bottom: 4px; }\n.slip-divider { font-weight: bold; letter-spacing: -1px; text-align: center; margin: 4px 0; }\n.slip-row { display: flex; justify-content: space-between; margin-bottom: 3px; }\n.slip-total { font-size: 13px; font-weight: bold; border-top: 1px dashed #000; border-bottom: 1px dashed #000; padding: 4px 0; margin: 4px 0; }\n.slip-footer { text-align: center; margin-top: 10px; font-size: 11px; }\n.slip-credits { font-size: 9px; margin-top: 6px; font-weight: bold; color: #333; }\n\n/* Responsive Mobile Layout */\n@media (max-width: 900px) {\n    .metrics-grid {\n        grid-template-columns: repeat(2, 1fr);\n    }\n}\n\n@media (max-width: 768px) {\n    .metrics-grid { grid-template-columns: 1fr; }\n    .hide-mobile { display: none; }\n    .grid-2 { grid-template-columns: 1fr; }\n    .span-2 { grid-column: span 1; }\n    \n    .kt-sidebar {\n        position: fixed;\n        top: 64px; bottom: 0; left: 0;\n        transform: translateX(-100%);\n    }\n    \n    .kt-sidebar.active {\n        transform: translateX(0);\n        box-shadow: 10px 0 30px rgba(0,0,0,0.8);\n    }\n}\n\n/* Modal Receipt Specific Layout */\n.modal-receipt {\n    max-width: 500px;\n}\n\n.modal-receipt .modal-body {\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    background: rgba(0, 0, 0, 0.4);\n    padding: 20px;\n    overflow-y: auto;\n    max-height: 65vh;\n}\n\n.modal-receipt .modal-footer {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 12px;\n    padding: 16px 20px;\n    background: #0f141c;\n    border-top: 1px solid var(--border-color);\n}\n\n/* Thermal Print Media Rules */\n@media print {\n    body * { visibility: hidden; }\n    .kt-thermal-slip, .kt-thermal-slip * { visibility: visible; }\n    .kt-thermal-slip {\n        position: absolute;\n        left: 0; top: 0;\n        width: 80mm;\n        padding: 0;\n        box-shadow: none;\n    }\n}\n\n/* Toast Notification System */\n.kt-toast-container {\n    position: fixed;\n    top: 80px;\n    right: 24px;\n    z-index: 10000;\n    display: flex;\n    flex-direction: column;\n    gap: 10px;\n    pointer-events: none;\n}\n\n.kt-toast {\n    background: rgba(22, 27, 34, 0.95);\n    backdrop-filter: blur(16px);\n    -webkit-backdrop-filter: blur(16px);\n    border: 1px solid rgba(255, 255, 255, 0.15);\n    border-left: 4px solid var(--primary);\n    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.7);\n    border-radius: var(--radius-md);\n    padding: 14px 20px;\n    color: var(--text-main);\n    font-size: 14px;\n    font-weight: 500;\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    animation: toastIn 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;\n    pointer-events: auto;\n    max-width: 400px;\n}\n\n.kt-toast-success { border-left-color: var(--success); }\n.kt-toast-danger { border-left-color: var(--danger); }\n.kt-toast-warning { border-left-color: var(--warning); }\n\n@keyframes toastIn {\n    from { opacity: 0; transform: translateX(50px) scale(0.9); }\n    to { opacity: 1; transform: translateX(0) scale(1); }\n}\n\n@keyframes toastOut {\n    from { opacity: 1; transform: translateX(0) scale(1); }\n    to { opacity: 0; transform: translateX(50px) scale(0.9); }\n}\n";
